clean(df):
    df['Price'] = pd.to_numeric(df['Price'].str.replace(r'[^0-9.]', '', regex=True), errors='coerce')
    return df

answer(df):
    allowed = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
    filtered = df[df['Category'].isin(allowed)]
    if filtered.empty:
        return {}
    grouped = filtered.groupby('Category')['Price'].mean()
    return {cat: mean for cat, mean in grouped.items()}
